do $reg$
declare
  S jsonb := $nhlreg${"schema":"edgedesk_research_registration_v1","model_key":"NHL-GOALIE-V2","name":"NHL goalie rating v2: shrunk current-season GSAx blended with prior seasons","version":"0.1","status":"EXPERIMENTAL","provenance":"T3","provenance_label":"EdgeDesk research","sport":"NHL","registered_at":"2026-10-25","hypothesis":"A goalie rating that shrinks his current-season goals saved above expected toward his own prior-seasons rating (itself shrunk toward replacement level) predicts the goalie-aware variant's moneyline and goals better than the v1 rating, which is one exponentially decayed career accumulation (200-day half-life) shrunk toward replacement level by 250 xG faced, so that early in a season the current season barely moves it.","objective":"Lower the out-of-sample moneyline log loss of the goalie-aware variant (xg_goalie_confirmed, confirmed starters) by replacing the v1 goalie rating with the v2 rating, without worse calibration or worse totals, before it may drive any goalie pairing on a live card.","primary_metric":"Paired difference in moneyline log loss (v2 minus v1) of the goalie-aware variant with the actual starters, held-out games.","unit":"One NHL game. Historical windows: every scored game of the walk-forward (hockey/model/walkforward.js protocol: predicted 30 minutes before the start from games on earlier dates only). Live holdout: a 2026-27 regular-season game whose two starters were Confirmed by T-30 in public.nhl_goalie_starters (source consensus), priced by both ratings from the same inputs.","baseline":"The v1 goalie rating as served (hockey/model/ratings.js goalieRating; hockey/model/params/live.json ratings: goalie_half_life_days 200, goalie_prior_xg 250, goalie_prior_rate -0.03) inside the same goalie-aware variant. Unchanged; the production price (xg_core) carries no goalie term and is not part of this test.","training_window":"The goalie-aware GLM is refitted per season on the five seasons before it, exactly as the walk-forward fits v1 (hockey/model/walkforward.js rule 2), with the v2 rating in the goalie_conf feature. The v2 constants below are fixed in advance and are not fitted.","validation_window":"The walk-forward CONFIRMATION window, 2020-21 through 2025-26 (seasons 2021-2026), scored once. The SELECTION window (2013-14 through 2019-20) is reported but decides nothing.","holdout_window":"2026-27 regular-season games starting from 2026-10-26 (Eastern) through the end of the regular season, evaluated once after the last regular-season game. Games through 2026-10-25 are excluded: the Minnesota at Vancouver game of 2026-10-25 (Lankinen projected, Merilainen started) was examined at registration.","machine":{"window_dates":{"training":null,"validation":["2020-10-01","2026-07-01"],"holdout":["2026-10-26","2027-04-17"]},"window_note":"[from, to): Eastern dates of the games inside each window","minimum_sample":500,"version":"0.1","status":"EXPERIMENTAL","provenance":"T3"},"minimum_sample":{"validation_games":6000,"holdout_games_confirmed_by_t30":500,"note":"Below either sample the window is reported descriptively and no result row is written. The holdout counts only games with both starters Confirmed by T-30 in the starter sync (the readiness view's KPI); games the sync did not confirm are listed, not imputed."},"promotion_criteria":{"decision_rule":"passed = true only if every criterion below holds. A criterion that cannot be evaluated (too few games, a missing window) is not met. Validation is scored once, the holdout once, after the regular season; no interim look decides anything. Passing makes v2 eligible; a person promotes it through a validation report, and until then nhl_goalie_config.live_goalie_variant stays xg_goalie_confirmed with the v1 rating and the card trigger refuses any other.","criteria":[{"id":"C1_VALIDATION_LOG_LOSS","rule":"Confirmation window: mean paired moneyline log loss difference (v2 - v1) <= -0.0005, and the 95% upper bound of the date-blocked bootstrap (2000 resamples, seed 20261025) is below 0."},{"id":"C2_HOLDOUT_LOG_LOSS","rule":"Live holdout (games Confirmed by T-30): mean paired difference (v2 - v1) <= 0. Reported with its interval; no significance is required of the live season alone."},{"id":"C3_CALIBRATION","rule":"On both windows the v2 variant's moneyline calibration slope is in [0.85, 1.15] and |mean p - mean y| <= 0.02 (the walk-forward's OUTCOME_VALIDATED rules)."},{"id":"C4_TOTALS_GUARD","rule":"Confirmation window: the Poisson deviance of regulation goals (both teams) is not worse than v1's by more than 0.1% of v1's deviance."},{"id":"C5_LEAKAGE","rule":"Zero leakage violations in the walk-forward audit (engine/validation.js): every current-season and prior-season quantity comes from games before the predicted game's date."}],"family_correction":"C1 and C2 are both required (an intersection test); no criterion is reported as a pass on its own."},"forking_paths":{"candidates_tried":[{"version":"0.1","current_season_shrink_xg":100,"prior_season_weights":[1,0.6,0.3],"prior_shrink_xg":150,"replacement_rate":-0.03,"evaluated_against_outcomes":false}],"alternatives_considered_not_tried":["Current-season GSAx alone, shrunk toward replacement level (discards everything known about the goalie before October).","Other prior-season weights (1/0.5/0.25, or equal weights) and other shrinkage weights (50 or 200 xG).","A hierarchical model with goalie random effects by season.","Save percentage or high-danger save percentage instead of goals saved above expected (ignores shot quality).","Re-tuning v1's half-life or prior on recent seasons (that is a v1 change, out of scope)."],"choice_and_reason":"One candidate, written before any evaluation: the current season is shrunk toward the goalie's own track record rather than toward replacement level, which is the gap the 2026-10-25 case exposed (a goalie with a poor start keeps most of his v1 rating); the weights and shrinkage are round values of the same order as v1's own (250 xG), not fitted.","data_already_seen":"At registration the only outcome examined was the 2026-10-25 Minnesota at Vancouver game: EdgeDesk's usage projection named Kevin Lankinen (v1 rating -0.0765 goals per xG faced; reported this season .786 save percentage and -10.7 GSAx in 6 games) and Leevi Merilainen started. No backtest of v2 has been run."},"spec":{"rating":"v2(i, D) = ((xGA_cs - GA_cs) + prior(i, D) * K_cs) / (xGA_cs + K_cs), where xGA_cs and GA_cs are the goalie's expected goals and goals against faced in the current season before date D (all situations, the same xG and attribution the v1 rating reads: team_games g1/g2 xga and ga), and K_cs = 100 xG.","prior":"prior(i, D) = (sum_s w_s (xGA_s - GA_s) + r0 * K0) / (sum_s w_s xGA_s + K0) over the three seasons before the current one (s = S-1, S-2, S-3), w = (1.0, 0.6, 0.3), K0 = 150 xG, r0 = -0.03 (replacement level, the v1 prior rate). A goalie with no NHL history has prior = r0.","feature":"goalie_conf in hockey/model/glm.js, unchanged: the opposing starter's rating, v2 in place of v1. The production candidate xg_core, the GLM features, the pair calibration rule and the distribution are untouched.","where_it_may_run":"Research only: a walk-forward variant beside v1 (to be written as hockey/research/goalie_v2/evaluate.js, which writes the validation report and no registry result). It may not price a live card: supabase/nhl_goalie_layer.sql refuses a card whose goalie_variant is not nhl_goalie_config.live_goalie_variant.","inputs":"hockey/data/team_games/<season>/*.csv (goalie xGA and GA per game), the same files v1 reads."},"result":null,"content_sha256":"b589eea3b9c5a00343beb88ef35af47c16d8f0ac60d8f176e2e5476be581acab"}$nhlreg$::jsonb;
  m regclass := 'public.research_models';
  v regclass := 'public.research_model_versions';
  mv jsonb; vv jsonb; mach jsonb := S -> 'machine';
  kcol text; ncol text; refcol text; fkcol text; vcol text; vid text; c text; ref text; vref text; have boolean;
  pairs text[][] := array[
    array['training_window', 'train_window', 'training_period', 'training'],
    array['validation_window', 'valid_window', 'validation_period', 'validation'],
    array['holdout_window', 'holdout_period', 'holdout', 'test_window']];
  wkeys text[] := array['training', 'validation', 'holdout'];
  i int;
begin
  kcol := pg_temp.edr_has(m, array['model_key', 'key', 'model_name', 'model', 'slug', 'code', 'name']);
  if kcol is null then raise exception 'research registry: research_models has no key column (model_key, key, model_name, model, slug, code or name) — nothing was registered'; end if;
  select a.attname::text, ra.attname::text into fkcol, refcol
    from pg_constraint k
    join pg_attribute a on a.attrelid = k.conrelid and a.attnum = k.conkey[1]
    join pg_attribute ra on ra.attrelid = k.confrelid and ra.attnum = k.confkey[1]
   where k.contype = 'f' and k.conrelid = v and k.confrelid = m limit 1;
  if fkcol is null then
    fkcol := pg_temp.edr_has(v, array['model_key', 'model_id', 'research_model_id', 'model']);
    refcol := case when fkcol in ('model_id', 'research_model_id') then pg_temp.edr_has(m, array['id', 'model_id']) else kcol end;
  end if;
  if fkcol is null or refcol is null then raise exception 'research registry: cannot tell how research_model_versions points at research_models — nothing was registered'; end if;
  vcol := pg_temp.edr_has(v, array['version', 'model_version', 'version_label', 'semver', 'label']);
  vid := pg_temp.edr_has(v, array['id', 'version_id', 'model_version_id']);

  execute format('select %I::text from %s where %I::text = $1 limit 1', refcol, m, kcol) into ref using S ->> 'model_key';
  if ref is null then
    mv := jsonb_build_object(kcol, S ->> 'model_key');
    ncol := pg_temp.edr_has(m, array['name', 'title', 'display_name', 'label']);
    if ncol is not null and ncol <> kcol then mv := mv || jsonb_build_object(ncol, S ->> 'name'); end if;
    foreach c in array array['title', 'display_name'] loop
      if c <> kcol and pg_temp.edr_has(m, array[c]) is not null and not (mv ? c) then mv := mv || jsonb_build_object(c, S ->> 'name'); end if;
    end loop;
    c := pg_temp.edr_has(m, array['sport', 'league']); if c is not null then mv := mv || jsonb_build_object(c, 'NHL'); end if;
    c := pg_temp.edr_has(m, array['sport_key']); if c is not null then mv := mv || jsonb_build_object(c, 'icehockey_nhl'); end if;
    c := pg_temp.edr_has(m, array['status', 'model_status', 'maturity']); if c is not null then mv := mv || jsonb_build_object(c, pg_temp.edr_label(m, c, array['experimental'])); end if;
    c := pg_temp.edr_has(m, array['provenance', 'evidence_provenance', 'tier', 'evidence_tier']);
    if c is not null then mv := mv || jsonb_build_object(c, pg_temp.edr_label(m, c, array['t3', 'research_model', 'research', 'model'])); end if;
    c := pg_temp.edr_has(m, array['objective', 'goal']); if c is not null then mv := mv || jsonb_build_object(c, S ->> 'objective'); end if;
    c := pg_temp.edr_has(m, array['hypothesis']); if c is not null then mv := mv || jsonb_build_object(c, S ->> 'hypothesis'); end if;
    c := pg_temp.edr_has(m, array['description', 'summary']); if c is not null then mv := mv || jsonb_build_object(c, S ->> 'hypothesis'); end if;
    c := pg_temp.edr_has(m, array['family', 'category', 'module', 'domain']); if c is not null then mv := mv || jsonb_build_object(c, 'nhl_goalies'); end if;
    c := pg_temp.edr_has(m, array['owner', 'created_by', 'registered_by']); if c is not null then mv := mv || jsonb_build_object(c, (S ->> 'registered_at') || ' preregistration (EdgeDesk research)'); end if;
    c := pg_temp.edr_has(m, array['metadata', 'meta', 'spec', 'details', 'config']);
    if c is not null then mv := mv || jsonb_build_object(c, pg_temp.edr_val(m, c, null, S, null)); end if;
    ref := pg_temp.edr_insert(m, mv, refcol);
    raise notice 'research registry: % registered', S ->> 'model_key';
  else
    raise notice 'research registry: % was already registered and is left as it is', S ->> 'model_key';
  end if;

  if vcol is not null then
    execute format('select exists (select 1 from %s where %I::text = $1 and %I::text = $2)', v, fkcol, vcol) into have using ref, S ->> 'version';
  else
    execute format('select exists (select 1 from %s where %I::text = $1)', v, fkcol) into have using ref;
  end if;
  if not have then
    vv := jsonb_build_object(fkcol, ref);
    if vcol is not null then vv := vv || jsonb_build_object(vcol, S ->> 'version'); end if;
    c := pg_temp.edr_has(v, array['status', 'model_status', 'maturity']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_label(v, c, array['experimental'])); end if;
    c := pg_temp.edr_has(v, array['provenance', 'evidence_provenance', 'tier']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_label(v, c, array['t3', 'research_model', 'research', 'model'])); end if;
    for i in 1 .. 3 loop
      c := pg_temp.edr_has(v, pairs[i:i][1:4]::text[]);
      if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S ->> (wkeys[i] || '_window'),
        jsonb_build_object('from', mach -> 'window_dates' -> wkeys[i] -> 0, 'to', mach -> 'window_dates' -> wkeys[i] -> 1, 'description', S ->> (wkeys[i] || '_window')),
        mach -> 'window_dates' -> wkeys[i])); end if;
    end loop;
    c := pg_temp.edr_has(v, array['objective', 'goal']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S ->> 'objective', null, null)); end if;
    c := pg_temp.edr_has(v, array['hypothesis']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S ->> 'hypothesis', null, null)); end if;
    c := pg_temp.edr_has(v, array['min_sample', 'minimum_sample', 'min_n', 'sample_target']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, (S -> 'minimum_sample')::text,
      case when pg_temp.edr_typ(v, c) in ('jsonb', 'json') then S -> 'minimum_sample' else mach -> 'minimum_sample' end, null)); end if;
    c := pg_temp.edr_has(v, array['success_metric', 'primary_metric', 'metric']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S ->> 'primary_metric', null, null)); end if;
    c := pg_temp.edr_has(v, array['promotion_criteria', 'decision_rule', 'criteria', 'success_criteria']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S -> 'promotion_criteria' ->> 'decision_rule', S -> 'promotion_criteria', null)); end if;
    c := pg_temp.edr_has(v, array['forking_paths', 'forking_paths_disclosure', 'disclosure', 'garden_of_forking_paths']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, null, S -> 'forking_paths', null)); end if;
    c := pg_temp.edr_has(v, array['spec', 'metadata', 'meta', 'params', 'config', 'details', 'definition', 'protocol']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, null, S -> 'spec' || jsonb_build_object('content_sha256', S ->> 'content_sha256', 'registration', 'hockey/research/goalie_v2/registration.json'), null)); end if;
    c := pg_temp.edr_has(v, array['notes', 'description']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c,
      'Preregistered ' || (S ->> 'registered_at') || ': hockey/research/goalie_v2/registration.json sha256 ' || (S ->> 'content_sha256') || '. No result until a validation report writes one.', null, null)); end if;
    perform pg_temp.edr_insert(v, vv, fkcol);
  end if;

  -- the version row the evaluation stamps (NOT the live variant: that stays as it is)
  if vid is not null and vcol is not null then
    execute format('select %I::text from %s where %I::text = $1 and %I::text = $2 limit 1', vid, v, fkcol, vcol) into vref using ref, S ->> 'version';
  end if;
  vref := coalesce(vref, ref || ':' || (S ->> 'version'));
  insert into public.nhl_goalie_config (key, value, note) values
    ('goalie_v2_model_key', S ->> 'model_key', 'research_models key of the experimental goalie rating'),
    ('goalie_v2_version', S ->> 'version', 'the registered version an evaluation stamps'),
    ('goalie_v2_version_ref', vref, 'research_model_versions row (as text)'),
    ('goalie_v2_registration_sha256', S ->> 'content_sha256', 'hockey/research/goalie_v2/registration.json'),
    ('goalie_v2_live', 'false', 'v2 drives no live card until it passes its registered criteria and a person promotes it')
  on conflict (key) do update set value = excluded.value, updated_at = now();
end $reg$;

commit;

-- THE REPORT: the model as research_model_current reads it, and the link the sync stamps. Every row should say ok.
create or replace function pg_temp.edr_report() returns table (piece text, state text)
language plpgsql as $f$
declare j jsonb; s text; p text;
begin
  if to_regclass('public.research_model_current') is not null then
    execute 'select to_jsonb(r) from public.research_model_current r where lower(coalesce(to_jsonb(r) ->> ''model_key'', to_jsonb(r) ->> ''key'', to_jsonb(r) ->> ''model_name'', to_jsonb(r) ->> ''model'', to_jsonb(r) ->> ''name'')) = lower($1) limit 1'
      into j using 'NHL-GOALIE-V2';
  end if;
  s := lower(coalesce(j ->> 'status', j ->> 'model_status', j ->> 'maturity', ''));
  p := coalesce(j ->> 'passed', 'null');
  piece := '1 NHL-GOALIE-V2 is EXPERIMENTAL with no result';
  state := case when to_regclass('public.research_model_current') is null then 'CHECK THIS: research_model_current is not in this database'
                when j is null then 'CHECK THIS: not in research_model_current'
                when s <> 'experimental' then 'CHECK THIS: status reads ' || s
                when p = 'true' then 'CHECK THIS: a result row shows passed = true'
                else 'ok' end;
  return next;
  piece := '2 version 0.1 is named in nhl_goalie_config and live cards still use the v1 variant';
  state := case when (select value from public.nhl_goalie_config where key = 'goalie_v2_version') = '0.1'
                 and (select value from public.nhl_goalie_config where key = 'goalie_v2_version_ref') is not null
                 and (select value from public.nhl_goalie_config where key = 'live_goalie_variant') = 'xg_goalie_confirmed' then 'ok' else 'CHECK THIS' end;
  return next;
end $f$;
select * from pg_temp.edr_report();
